-- ============================================================
-- Catálogo de convênio (todos os ativos, sem ultrassom/check-up/interno) + preparo por exame
-- Gerado das planilhas LISTA DE EXAMES.csv + orientação de exames.csv
-- ============================================================
create table if not exists public.exame_preparo (
  nome_norm text primary key,
  jejum_horas int not null default 0,
  instrucoes jsonb not null default '[]'::jsonb,
  atualizado_em timestamptz not null default now()
);
create table if not exists public.exames_convenio (
  codigo_shift integer primary key,
  nome text not null,
  nome_norm text not null,
  ativo boolean not null default true,
  criado_em timestamptz not null default now()
);
create index if not exists idx_exames_convenio_norm on public.exames_convenio(nome_norm);
create index if not exists idx_exames_convenio_ativo on public.exames_convenio(ativo);

alter table public.exame_preparo enable row level security;
alter table public.exames_convenio enable row level security;
grant select on public.exame_preparo, public.exames_convenio to anon, authenticated;
grant insert, update, delete on public.exame_preparo, public.exames_convenio to authenticated;

drop policy if exists prep_sel on public.exame_preparo;
create policy prep_sel on public.exame_preparo for select using (true);
drop policy if exists prep_wr on public.exame_preparo;
create policy prep_wr on public.exame_preparo for all to authenticated
  using (public.has_role(auth.uid(),'admin'::app_role) or public.has_role(auth.uid(),'staff'::app_role))
  with check (public.has_role(auth.uid(),'admin'::app_role) or public.has_role(auth.uid(),'staff'::app_role));
drop policy if exists conv_sel on public.exames_convenio;
create policy conv_sel on public.exames_convenio for select using (true);
drop policy if exists conv_wr on public.exames_convenio;
create policy conv_wr on public.exames_convenio for all to authenticated
  using (public.has_role(auth.uid(),'admin'::app_role) or public.has_role(auth.uid(),'staff'::app_role))
  with check (public.has_role(auth.uid(),'admin'::app_role) or public.has_role(auth.uid(),'staff'::app_role));
truncate public.exames_convenio;
on conflict (nome_norm) do update set jejum_horas=excluded.jejum_horas, instrucoes=excluded.instrucoes, atualizado_em=now();
on conflict (codigo_shift) do update set nome=excluded.nome, nome_norm=excluded.nome_norm, ativo=true;
